            goals.append((int(r[0]), int(r[1])))
        elif isinstance(r, dict):
            gx = r.get("x", None)
            gy = r.get("y", None)
            if gx is not None and gy is not None:
                goals.append((int(gx), int(gy)))

    if rem > 0:
        goals.append((sx, sy))

    def in_bounds(x, y):
        return 0 <= x < grid_w and 0 <= y < grid_h

    obstacles_set = set()
    for ob in obstacles:
        if isinstance(ob, (list, tuple)) and len(ob) >= 2:
            obstacles_set.add((int(ob[0]), int(ob[1])))
        elif isinstance(ob, dict):
            ax = ob.get("x")
            ay = ob.get("y")
            if ax is not None and ay is not None:
                obstacles_set.add((int(ax), int(ay)))

    for gx, gy in goals:
        for dx_i in (-1, 0, 1):
            for dy_i in (-1, 0, 1):
                nx = sx + dx_i
                ny = sy + dy_i
                if not in_bounds(nx, ny):
                    continue
                if (nx, ny) in obstacles_set:
                    continue
                if dx_i == 0 and dy_i == 0:
                    continue
                dist = abs(gx - nx) + abs(gy - ny)
                score = -dist
                if (nx, ny) == (ox, oy):
                    score -= 5
                if (nx, ny) in self_path:
                    score -= 1
                if (nx, ny) in opp_path:
                    score -= 2
                if score > best_score:
                    best_score = score
                    best_dx = dx_i
                    best_dy = dy_i

    if best_score == -10**9:
        if sx != ox or sy != oy:
            dx_try = 0 if ox == sx else (1 if ox > sx else -1)
