            cand = [(dx_try, 0), (0, dy_try), (dx_try, dy_try)]
            for tx, ty in cand:
                nx, ny = sx + tx, sy + ty
                if in_bounds(nx, ny) and (nx, ny) not in obstacles_set:
                    return [tx, ty]
        return [0, 0]

    return [best_dx, best_dy]
